import sys;sys.path.insert(0,'.')
from common6 import *
SN=E('English','እንግሊዝኛ')
GB='en-GB'
def sq(sent,opts,a=0): return {'say':sent.replace('___',opts[a]),'sayLang':GB,'q':sent,'o':opts,'a':a}
def eq(en,am,opts,a=0,say=None):
    d={'q':E(en,am) if am else en,'o':[o if isinstance(o,str) else E(*o) for o in opts],'a':a}
    if say: d['say']=say;d['sayLang']=GB
    return d
def read(ptitle,paras,items):
    return {'title':E('Read and answer','አንብቡና መልሱ'),'type':'quiz','tip':E('Listen to the passage, read it yourself, then answer.','ጽሑፉን አዳምጡ፣ ራሳችሁ አንብቡ፣ ከዚያ መልሱ።'),'passage':{'title':ptitle,'paras':paras,'say':' '.join(paras),'sayLang':GB},'items':items}
def U(n,title,data,extra,exam,nt,summ):
    unit(f'g6-english-{n}','english',SN,E(f'Unit {n}',f'ክፍል {n}'),E(*title),E(f'Built on English for Ethiopia, Grade 6, Unit {n}: {title[0]}.',f'በEnglish for Ethiopia 6ኛ ክፍል፣ ክፍል {n} ({title[1]}) ላይ የተመሰረተ።'),'K1.engMissions',data,extra,exam,nt,summ)
def L(words): return [[w,e,a] for w,e,a in words]
def SP(*ws): return [{'w':w,'blanks':b,'e':e,'am':a} for w,b,e,a in ws]

